// Component catalogue schema (generated by scripts/import-components.mjs).
// Records that fail validation are skipped and counted instead of breaking the app.

import { REPO_PATH } from "./shell";

export const COMPONENT_TYPES = ["skill", "mcp", "cli", "dsh-plugin"] as const;
export type ComponentType = (typeof COMPONENT_TYPES)[number];

export const DOMAIN_GROUPS = ["literature", "omics", "drug", "clinical", "imaging", "tools"] as const;
export type DomainGroup = (typeof DOMAIN_GROUPS)[number];

export const RISK_LEVELS = ["green", "amber", "red", "grey"] as const;
export type RiskLevel = (typeof RISK_LEVELS)[number];

/** Harness roles of agent-mechanism plugins (orchestration, context and memory, evaluation feedback, permissions). */
export const MECHANISM_ROLES = ["orchestration", "contextMemory", "evaluationFeedback", "permissions"] as const;
export type MechanismRole = (typeof MECHANISM_ROLES)[number];

/** Paper a mechanism plugin was generated from; `url` is null unless it is an https link. */
export interface PaperSource { label: string; title: string; url: string | null; }

export interface ComponentSummary {
  id: string;
  name: string;
  type: ComponentType;
  repo: string;
  description: string;
  tags: string[];
  group: DomainGroup;
  domain: string;
  tasks: string[];
  /** null when no verified evaluation card is attached. */
  risk: RiskLevel | null;
  functionPrimary: string | null;
  /** Canonical function subcategories from the evaluation card; empty when not evaluated. */
  functionLabels: string[];
  /** Harness role of an agent-mechanism plugin; absent or null for tools. */
  mechanism?: MechanismRole | null;
  /** Short label of the source paper of a mechanism plugin. */
  paper?: string | null;
  /** A native DSH mechanism that paper plugins may replace (not a paper plugin). */
  native?: boolean;
}

export interface QualityAxis {
  key: string;
  label: string;
  score: number | null;
  source: string;
  notes?: string[];
  reason?: string;
  drivers?: string[];
}

export interface MedicalItem { code: string; label: string; text: string; evidence: string[]; }

export interface EvaluationCard {
  unitId: string;
  title: string;
  kind: string;
  source: string;
  compatibility: { state: string; label: string; warnings: string[] };
  risk: { verdict: string; level: RiskLevel; subcategory: string; threats: { type: string; subLabels: string[] }[]; lines: string[] };
  function: { status: string; primary: string | null; secondary: string | null; subLabels: string[] };
  behaviour: Record<string, string[]>;
  quality: QualityAxis[];
  medical: {
    status: string;
    groups: Record<string, MedicalItem[]>;
    codes: string[];
    noMedicalContent: boolean;
    noneReason: string;
    audience: string;
    authorStatements: { text: string; evidence: string[] }[];
    expertReview: boolean;
    undetermined: string;
    rejectedAll?: boolean;
    rejected?: { code: string; label: string; reason: string }[];
  };
  footer: string[];
  review: { status: string; valid: boolean; rejectedClaims: number };
}

export interface ComponentCapability { domain: string; subdomain: string; task: string; inputs: string[]; outputs: string[]; databases: string[]; }

export type LinkStatus = "unique" | "ambiguous" | "unmatched";

/** Catalogue relation types from component-relations.json, in display order. */
export const RELATION_TYPES = ["requires", "declared-use", "data-flow", "precedes", "shared-input", "wrapper", "composes_with", "contains", "alternative_to"] as const;
export type RelationType = (typeof RELATION_TYPES)[number];

export interface ComponentRelation { direction: "out" | "in"; type: RelationType; otherId: string; condition: string | null; }

/** Upstream install hint: the entry-index id used by `dsh-med inspect/install`. */
/** `formalInventory`: installed from the shipped formal-inventory directory (DSH_MED_FORMAL_INVENTORY). */
export interface InstallHint { entryId: string; installability: string; verification: string; trust: string; requires: string[]; formalInventory?: boolean; }

/** Directed catalogue edge between two components (ids). */
export interface CatalogueEdge { from: string; to: string; type: RelationType; }

export interface ComponentDetail {
  id: string;
  name: string;
  type: ComponentType;
  repo: string;
  provider: string;
  sourceName: string;
  sourceUrl: string;
  repositoryUrl: string;
  license: string | null;
  callable: boolean;
  aliases: string[];
  description: string;
  tags: string[];
  capabilities: ComponentCapability[];
  evaluation: EvaluationCard | null;
  link: { status: LinkStatus; cardUnitId?: string };
  install: InstallHint | null;
  relations: ComponentRelation[];
  mechanism?: MechanismRole | null;
  paper?: PaperSource | null;
  native?: boolean;
}

export interface UpstreamSource { branch: string; commit: string; path?: string; committedAt: string; }

export interface ComponentIndex {
  schemaVersion: "2";
  repository: string;
  upstream: Record<string, UpstreamSource>;
  components: ComponentSummary[];
  edges: CatalogueEdge[];
  skipped: number;
}

const isRecord = (value: unknown): value is Record<string, unknown> => typeof value === "object" && value !== null && !Array.isArray(value);
const isString = (value: unknown): value is string => typeof value === "string";
const isStringArray = (value: unknown): value is string[] => Array.isArray(value) && value.every(isString);
const oneOf = <T extends string>(values: readonly T[], value: unknown): value is T => values.includes(value as T);

const mechanismOf = (value: unknown): MechanismRole | null => (oneOf(MECHANISM_ROLES, value) ? value : null);
const HTTPS_URL = /^https:\/\//i;

function paperOf(value: unknown): PaperSource | null {
  if (!isRecord(value) || !isString(value.label)) return null;
  return { label: value.label, title: isString(value.title) ? value.title : "", url: isString(value.url) && HTTPS_URL.test(value.url) ? value.url : null };
}

export function isComponentSummary(value: unknown): value is Omit<ComponentSummary, "functionLabels"> & { functionLabels?: string[] } {
  if (!isRecord(value)) return false;
  return isString(value.id) && value.id.length > 0
    && isString(value.name) && oneOf(COMPONENT_TYPES, value.type) && isString(value.repo) && REPO_PATH.test(value.repo)
    && isString(value.description) && isStringArray(value.tags) && oneOf(DOMAIN_GROUPS, value.group)
    && isString(value.domain) && isStringArray(value.tasks)
    && (value.risk === null || oneOf(RISK_LEVELS, value.risk))
    && (value.functionPrimary === null || isString(value.functionPrimary))
    && (value.functionLabels === undefined || isStringArray(value.functionLabels));
}

export function parseComponentIndex(raw: unknown): ComponentIndex {
  if (!isRecord(raw) || raw.schemaVersion !== "2" || !Array.isArray(raw.components)) throw new Error("Unsupported component index");
  const seen = new Set<string>();
  const components: ComponentSummary[] = [];
  let skipped = 0;
  for (const item of raw.components) {
    if (!isComponentSummary(item) || seen.has(item.id)) { skipped += 1; continue; }
    seen.add(item.id);
    components.push({ ...item, functionLabels: item.functionLabels ?? [], mechanism: mechanismOf(item.mechanism), paper: isString(item.paper) && item.paper ? item.paper : null, native: item.native === true });
  }
  return { schemaVersion: "2", repository: isString(raw.repository) ? raw.repository : "", upstream: isRecord(raw.upstream) ? raw.upstream as Record<string, UpstreamSource> : {}, components, edges: parseEdges(raw.relations, raw.components), skipped };
}

/** Edges are stored as [fromPosition, toPosition, typeIndex] against the raw components array. */
function parseEdges(raw: unknown, rawComponents: unknown[]): CatalogueEdge[] {
  if (!isRecord(raw) || !isStringArray(raw.types) || !Array.isArray(raw.edges)) return [];
  const types = raw.types;
  const idAt = (position: unknown) => (typeof position === "number" && isRecord(rawComponents[position]) && isString(rawComponents[position].id) ? rawComponents[position].id as string : undefined);
  return raw.edges.flatMap(edge => {
    if (!Array.isArray(edge) || edge.length !== 3) return [];
    const from = idAt(edge[0]);
    const to = idAt(edge[1]);
    const type = typeof edge[2] === "number" ? types[edge[2]] : undefined;
    return from && to && oneOf(RELATION_TYPES, type) ? [{ from, to, type }] : [];
  });
}

function isEvaluationCard(value: unknown): value is EvaluationCard {
  if (!isRecord(value)) return false;
  return isString(value.unitId) && isRecord(value.risk) && oneOf(RISK_LEVELS, value.risk.level) && isString(value.risk.verdict)
    && isRecord(value.function) && Array.isArray(value.quality) && isRecord(value.medical) && isRecord(value.review);
}

const GITHUB_URL = /^https:\/\/github\.com\//;
const GITHUB_REPOSITORY_URL = /^https:\/\/github\.com\/[\w.-]+\/[\w.-]+$/;

/** Only GitHub https links are rendered; anything else falls back to the repository page. */
function githubUrl(value: unknown, repo: string): string {
  if (isString(value) && GITHUB_URL.test(value)) return value;
  return REPO_PATH.test(repo) ? `https://github.com/${repo}` : "https://github.com/";
}

/** Validates one detail record. An invalid evaluation is dropped, never guessed. */
export function parseComponentDetail(value: unknown): ComponentDetail | undefined {
  if (!isRecord(value) || !isString(value.id) || !isString(value.name) || !oneOf(COMPONENT_TYPES, value.type) || !isString(value.repo)) return undefined;
  const capabilities = Array.isArray(value.capabilities) ? value.capabilities.filter(isRecord).map(item => ({
    domain: isString(item.domain) ? item.domain : "", subdomain: isString(item.subdomain) ? item.subdomain : "", task: isString(item.task) ? item.task : "",
    inputs: isStringArray(item.inputs) ? item.inputs : [], outputs: isStringArray(item.outputs) ? item.outputs : [], databases: isStringArray(item.databases) ? item.databases : [],
  })) : [];
  const evaluation = isEvaluationCard(value.evaluation) ? value.evaluation : null;
  const install = isRecord(value.install) && isString(value.install.entryId) ? {
    entryId: value.install.entryId,
    installability: isString(value.install.installability) ? value.install.installability : "unknown",
    verification: isString(value.install.verification) ? value.install.verification : "unknown",
    trust: isString(value.install.trust) ? value.install.trust : "unknown",
    requires: isStringArray(value.install.requires) ? value.install.requires : [],
    ...(value.install.formalInventory === true ? { formalInventory: true } : {}),
  } : null;
  const relations: ComponentRelation[] = Array.isArray(value.relations) ? value.relations.filter(isRecord).flatMap((item): ComponentRelation[] => (
    (item.direction === "out" || item.direction === "in") && oneOf(RELATION_TYPES, item.type) && isString(item.otherId)
      ? [{ direction: item.direction, type: item.type, otherId: item.otherId, condition: isString(item.condition) ? item.condition : null }]
      : [])) : [];
  const link = isRecord(value.link) && oneOf(["unique", "ambiguous", "unmatched"] as const, value.link.status) ? value.link.status : "unmatched";
  return {
    id: value.id, name: value.name, type: value.type, repo: value.repo,
    provider: isString(value.provider) ? value.provider : "",
    sourceName: isString(value.sourceName) ? value.sourceName : "",
    sourceUrl: githubUrl(value.sourceUrl, value.repo),
    // Used in a copied `git clone` command, so only an exact owner/name URL is accepted.
    repositoryUrl: isString(value.repositoryUrl) && GITHUB_REPOSITORY_URL.test(value.repositoryUrl) ? value.repositoryUrl : githubUrl(undefined, value.repo),
    license: isString(value.license) ? value.license : null,
    callable: value.callable === true,
    aliases: isStringArray(value.aliases) ? value.aliases : [],
    description: isString(value.description) ? value.description : "",
    tags: isStringArray(value.tags) ? value.tags : [],
    capabilities,
    evaluation,
    link: evaluation && link === "unique" ? { status: "unique", cardUnitId: evaluation.unitId } : { status: link === "unique" ? "unmatched" : link },
    install,
    relations,
    mechanism: mechanismOf(value.mechanism),
    paper: paperOf(value.paper),
    native: value.native === true,
  };
}

export function parseComponentDetailShard(raw: unknown): Map<string, ComponentDetail> {
  const result = new Map<string, ComponentDetail>();
  if (!isRecord(raw) || !isRecord(raw.components)) return result;
  for (const value of Object.values(raw.components)) {
    const detail = parseComponentDetail(value);
    if (detail) result.set(detail.id, detail);
  }
  return result;
}

/** Lower-cased text used by list search; built once per record. */
export function searchText(item: ComponentSummary): string {
  return [item.name, item.id, item.repo, item.paper ?? "", item.description, item.domain, item.functionPrimary ?? "", ...item.functionLabels, ...item.tags, ...item.tasks].join(" ").toLowerCase();
}
